// Фильтруем строки, где есть номер тикета (начиная со 2-й строки)
const items = $input.all();
const filtered = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const ticketNumber = item.json['№ Тикета'];
  // Пропускаем первую строку (заголовки) и берем только строки с тикетами
  if (i > 0 && ticketNumber && ticketNumber !== '' && ticketNumber !== null && ticketNumber !== undefined) {
    filtered.push(item);
  }
}

return filtered;

// Функция для расчета разницы времени
function calculateTimeDifference(date1, time1, date2, time2) {
  // Нормализуем формат даты
  function normalizeDate(dateStr) {
    // Если дата в формате ДД.ММ.ГГГГ, преобразуем в ГГГГ-ММ-ДД
    if (dateStr.includes('.')) {
      const parts = dateStr.split('.');
      if (parts.length === 3) {
        return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
    }
    return dateStr;
  }

  // Нормализуем формат времени
  function normalizeTime(timeStr) {
    // Убираем секунды, если есть
    return timeStr.length > 5 ? timeStr.substring(0, 5) : timeStr;
  }

  const normalizedDate1 = normalizeDate(date1);
  const normalizedDate2 = normalizeDate(date2);
  const normalizedTime1 = normalizeTime(time1);
  const normalizedTime2 = normalizeTime(time2);

  // Формируем полные даты
  const datetime1 = new Date(`${normalizedDate1} ${normalizedTime1}`);
  const datetime2 = new Date(`${normalizedDate2} ${normalizedTime2}`);

  if (isNaN(datetime1.getTime()) || isNaN(datetime2.getTime())) {
    return 'Ошибка: неверный формат даты/времени';
  }

  // Вычисляем разницу в миллисекундах
  const diff = Math.abs(datetime2 - datetime1);

  // Конвертируем в дни, часы, минуты, секунды
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));
  const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
  const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
  const seconds = Math.floor((diff % (1000 * 60)) / 1000);

  return `${days}д ${hours}ч ${minutes}м ${seconds}с`;
}

// Получаем данные из текущей строки
const item = $input.item.json;

// Первый расчет: Время передачи + Дата передачи -> Время возврата + Дата возврата
let result1 = '';
if (item['Дата передачи'] && item['Время передачи'] && 
    item['Дата возврата'] && item['Время возврата']) {
  try {
    result1 = calculateTimeDifference(
      item['Дата передачи'],
      item['Время передачи'],
      item['Дата возврата'],
      item['Время возврата']
    );
  } catch (error) {
    result1 = `Ошибка: ${error.message}`;
  }
}

// Второй расчет: Время передачи + Дата передачи -> Время взятия тикета + Дата взятия тикета
let result2 = '';
if (item['Дата передачи'] && item['Время передачи'] && 
    item['Дата взятия тикета в работу сотрудником ЦКП'] && 
    item['Время взятия тикета в работу сотрудником ЦКП']) {
  try {
    result2 = calculateTimeDifference(
      item['Дата передачи'],
      item['Время передачи'],
      item['Дата взятия тикета в работу сотрудником ЦКП'],
      item['Время взятия тикета в работу сотрудником ЦКП']
    );
  } catch (error) {
    result2 = `Ошибка: ${error.message}`;
  }
}

// Возвращаем данные с результатами
return {
  json: {
    ...item,
    'Время обработки': result1,
    'Время с момента передачи тикета до взятия его обратно в работу сотрудниками ЦКП': result2
  }
};
